-- Anki-NF-1412 to Anki-NF-1421: IPv6 multicast scope tip in list form (applied AFTER the IPv6 Jeremy rewrite, which had reverted it to paragraph).
-- 8 questions use 'Read the scope from the second byte:' + FF01/FF02/FF05/FF08/FF0E list.
-- 2 questions (1415, 1419) use Jeremy's 'Read the scope from the 4th hex character:' + 1/2/5/8/E list.
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv6 Multicast Scope</div><p>The second byte of an IPv6 multicast address (FF0x) carries the scope. The scope limits how far the packet travels.</p><ul><li>1 = interface-local, the message does not leave the local device</li><li>2 = link-local, stays in the local subnet</li><li>5 = site-local, only within one physical site</li><li>8 = organization-local, wider than site-local</li><li>E = global, can be routed over the public internet</li></ul></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>FF01</strong>: FF01 is the scope value for Interface-local.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>FF05</strong>: This is the scope value for Site-local, not Interface-local.</li><li><span class="opt-tag wrong">Option C</span> <strong>FF08</strong>: This is the scope value for Organization-local, not Interface-local.</li><li><span class="opt-tag wrong">Option D</span> <strong>FF02</strong>: This is the scope value for Link-local, not Interface-local.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><p>Read the scope from the second byte:</p><ul><li>FF01 interface.</li><li>FF02 link.</li><li>FF05 site.</li><li>FF08 organization.</li><li>FF0E global.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div></div>' WHERE question_no = 'Anki-NF-1412';
UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv6 Multicast Scope</div><p>The second byte of an IPv6 multicast address (FF0x) carries the scope. Scope says how far the packet can travel. 1 is the interface itself, 2 is the local link, 5 is the site, 8 is the organization, and E (14) is global.</p></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option B) is Correct:</h4><ul><li><span class="opt-tag correct">Option B</span> <strong>Interface-local</strong>: FF01 means Interface-local scope. The message does not leave the local device.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>Site-local</strong>: That is the FF05 scope, not Interface-local.</li><li><span class="opt-tag wrong">Option C</span> <strong>Link-local</strong>: That is the FF02 scope, not Interface-local.</li><li><span class="opt-tag wrong">Option D</span> <strong>Global</strong>: That is the FF0E scope, not Interface-local.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><p>Read the scope from the second byte:</p><ul><li>FF01 interface.</li><li>FF02 link.</li><li>FF05 site.</li><li>FF08 organization.</li><li>FF0E global.</li></ul></div>
<div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div>
</div>' WHERE question_no = 'Anki-NF-1413';
UPDATE questions SET explanation = '<div class="explanation-rich-content">
<div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv6 Multicast Scope</div><p>The second byte of a multicast address, FF0x, tells you the scope.</p><p>The scope limits how far the packet travels.</p></div>
  <div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option D) is Correct:</h4><ul><li><span class="opt-tag correct">Option D</span> <strong>FF02</strong>: <strong>FF02</strong> is the scope value for <strong>Link-local</strong>.</li></ul></div>
  <div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option A</span> <strong>FF0E</strong>: This is the scope value for <strong>Global</strong>, not Link-local.</li><li><span class="opt-tag wrong">Option B</span> <strong>FF01</strong>: This is the scope value for <strong>Interface-local</strong>, not Link-local.</li><li><span class="opt-tag wrong">Option C</span> <strong>FF05</strong>: This is the scope value for <strong>Site-local</strong>, not Link-local.</li></ul></div>
<div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><p>Read the scope from the second byte:</p><ul><li>FF01 interface.</li><li>FF02 link.</li><li>FF05 site.</li><li>FF08 organization.</li><li>FF0E global.</li></ul></div>
<div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div>
</div>' WHERE question_no = 'Anki-NF-1414';
UPDATE questions SET explanation = '<div class="explanation-rich-content"><div class="expl-card concept-card"><div class="section-title-concept">📌 Core Concept: IPv6 Multicast Scope</div><p>The 4th hex character of a multicast address tells you its scope. The scope limits how far the packet travels.</p><ul><li>FF01 = interface-local. The message does not leave the local device.</li><li>FF02 = link-local. It stays in the local subnet and is not routed between subnets.</li><li>FF05 = site-local. FF08 = organization-local. FF0E = global.</li></ul></div><div class="expl-card correct-card"><h4 class="section-title-correct">✓ Why the Correct Answer (Option A) is Correct:</h4><ul><li><span class="opt-tag correct">Option A</span> <strong>Link-local</strong>: FF02 means link-local scope. The packet stays on the local link.</li></ul></div><div class="expl-card incorrect-card"><h4 class="section-title-incorrect">✗ Why Other Options are Incorrect:</h4><ul><li><span class="opt-tag wrong">Option B</span> <strong>Interface-local</strong>: That is the FF01 scope, not FF02.</li><li><span class="opt-tag wrong">Option C</span> <strong>Organization-local</strong>: That is the FF08 scope, not FF02.</li><li><span class="opt-tag wrong">Option D</span> <strong>Site-local</strong>: That is the FF05 scope, not FF02.</li></ul></div><div class="expl-card tip-card"><h4 class="section-title-tip">💡 CCNA Exam Tip:</h4><p>Read the scope from the 4th hex character:</p><ul><li>1 interface.</li><li>2 link.</li><li>5 site.</li><li>8 organization.</li><li>E global.</li></ul></div><div class="expl-card concept-card"><div class="section-title-concept">📌 Source: Anki Flashcards - Network Fundamentals (CCNA / Day 32 Flashcards - IPv6 (Part 2)</div></div></div>' WHERE question_no = 'Anki-NF-1415';
